#ifndef VG_FAIL
#define VG_FAIL
static jmp_buf vg_test_jump;
static bool vg_in_test = false;
static const char* vg_failure = "";
static void vg_fail(const char* message) {
    vg_failure = message;
    if (vg_in_test) longjmp(vg_test_jump, 1);
    fflush(stdout);
    fprintf(stderr, "Error: %s\n", message);
    exit(1);
}
#endif

helpers.vg_copy:
#ifndef VG_COPY
#define VG_COPY
// Text is never freed: generated programs are short-lived.
static char* vg_copy(const char* text, size_t length) {
    char* copy = (char*)malloc(length + 1);
    memcpy(copy, text, length);
    copy[length] = '\0';
    return copy;
}
#endif

