helpers.vg_to_number:
#ifndef VG_TO_NUMBER
#define VG_TO_NUMBER
static double vg_to_number(const char* text) {
    while (*text == ' ' || (*text >= '\t' && *text <= '\r')) text++;
    if (!*text) return 0;
    char* end;
    double value = strtod(text, &end);
    while (*end == ' ' || (*end >= '\t' && *end <= '\r')) end++;
    return *end ? NAN : value;
}
#endif

