#ifndef VG_VALUE
#define VG_VALUE
typedef enum { VG_NONE, VG_BOOL, VG_INT, VG_FLOAT, VG_STRING } VgKind;
typedef struct { VgKind kind; bool b; long long i; double f; const char* s; } VgValue;
static VgValue vg_none(void) { VgValue v = { VG_NONE, false, 0, 0, "" }; return v; }
static VgValue vg_bool(bool b) { VgValue v = { VG_BOOL, b, 0, 0, "" }; return v; }
static VgValue vg_int(long long i) { VgValue v = { VG_INT, false, i, 0, "" }; return v; }
static VgValue vg_float(double f) { VgValue v = { VG_FLOAT, false, 0, f, "" }; return v; }
static VgValue vg_string(const char* s) { VgValue v = { VG_STRING, false, 0, 0, s }; return v; }
static double vg_as_float(VgValue v) { return v.kind == VG_FLOAT ? v.f : v.kind == VG_INT ? (double)v.i : v.kind == VG_BOOL ? (v.b ? 1 : 0) : v.kind == VG_STRING ? vg_to_number(v.s) : 0; }
static long long vg_as_int(VgValue v) { return v.kind == VG_INT ? v.i : (long long)vg_as_float(v); }
static bool vg_as_bool(VgValue v) { return v.kind == VG_BOOL ? v.b : v.kind == VG_STRING ? v.s[0] != '\0' : vg_as_float(v) != 0; }
static const char* vg_as_string(VgValue v) { return v.kind == VG_STRING ? v.s : ""; }
#endif

helpers.vg_text_any:
#ifndef VG_TEXT_ANY
#define VG_TEXT_ANY
static const char* vg_text_any(VgValue v) {
    switch (v.kind) {
        case VG_BOOL: return v.b ? "true" : "false";
        case VG_INT: return vg_text_int(v.i);
        case VG_FLOAT: return vg_text_float(v.f);
        case VG_STRING: return v.s;
        default: return "";
    }
}
#endif

helpers.vg_parse_float:
#ifndef VG_PARSE_FLOAT
#define VG_PARSE_FLOAT
static double vg_parse_float(const char* text) {
    const char* p = text;
    while (*p == ' ' || (*p >= '\t' && *p <= '\r')) p++;
    const char* start = p;
    if (*p == '+' || *p == '-') p++;
    int digits = 0;
    while (*p >= '0' && *p <= '9') { p++; digits++; }
    if (*p == '.') { p++; while (*p >= '0' && *p <= '9') { p++; digits++; } }
    if (!digits) return 0;
    if (*p == 'e' || *p == 'E') {
        const char* e = p + 1;
        if (*e == '+' || *e == '-') e++;
        if (*e < '0' || *e > '9') return 0;
        while (*e >= '0' && *e <= '9') e++;
        p = e;
    }
    while (*p == ' ' || (*p >= '\t' && *p <= '\r')) p++;
    if (*p) return 0;
    return strtod(start, NULL);
}
#endif

helpers.vg_parse_int:
#ifndef VG_PARSE_INT
#define VG_PARSE_INT
static long long vg_parse_int(const char* text) {
    const char* p = text;
    while (*p == ' ' || (*p >= '\t' && *p <= '\r')) p++;
    const char* start = p;
    if (*p == '+' || *p == '-') p++;
    if (*p < '0' || *p > '9') return 0;
    while (*p >= '0' && *p <= '9') p++;
    while (*p == ' ' || (*p >= '\t' && *p <= '\r')) p++;
    return *p ? 0 : strtoll(start, NULL, 10);
}
#endif

helpers.vg_substring:
#ifndef VG_SUBSTRING
#define VG_SUBSTRING
static const char* vg_substring(const char* text, long long start, long long count) {
    if (start < 0) start = 0;
    if (count < 0) count = 0;
    const char* p = text;
    for (long long i = 0; i < start && *p; i++) do p++; while ((*p & 0xC0) == 0x80);
    const char* from = p;
    for (long long i = 0; i < count && *p; i++) do p++; while ((*p & 0xC0) == 0x80);
    return vg_copy(from, (size_t)(p - from));
}
#endif

helpers.vg_replace:
#ifndef VG_REPLACE
#define VG_REPLACE
static const char* vg_replace(const char* text, const char* find, const char* replacement) {
    size_t f = strlen(find), r = strlen(replacement), length = 0;
    if (!f) return text;
    for (const char* p = text; (p = strstr(p, find)); p += f) length++;
    char* result = (char*)malloc(strlen(text) + length * r + 1);
    char* out = result;
    for (const char* p = text;;) {
        const char* at = strstr(p, find);
        if (!at) { strcpy(out, p); break; }
        memcpy(out, p, (size_t)(at - p));
        out += at - p;
        memcpy(out, replacement, r);
        out += r;
        p = at + f;
    }
    return result;
}
#endif

helpers.vg_change_case:
#ifndef VG_CHANGE_CASE
#define VG_CHANGE_CASE
// ASCII letters only, as the C++ and Rust packs do.
static const char* vg_change_case(const char* text, bool upper) {
    size_t length = strlen(text);
    char* result = vg_copy(text, length);
    for (size_t i = 0; i < length; i++) {
        if (upper && result[i] >= 'a' && result[i] <= 'z') result[i] = (char)(result[i] - 32);
        if (!upper && result[i] >= 'A' && result[i] <= 'Z') result[i] = (char)(result[i] + 32);
    }
    return result;
}
#endif

helpers.vg_trim:
#ifndef VG_TRIM
#define VG_TRIM
static const char* vg_trim(const char* text) {
    while (*text == ' ' || (*text >= '\t' && *text <= '\r')) text++;
    size_t length = strlen(text);
    while (length && (text[length - 1] == ' ' || (text[length - 1] >= '\t' && text[length - 1] <= '\r'))) length--;
    return vg_copy(text, length);
}
#endif

