#include "{{file}}"

int main(int argc, char** argv) {
    if (argc > 1 && strcmp(argv[1], "--test") == 0) {
        int failed = 0;
        for (int i = 2; i + 1 < argc; i += 2) {
            if (vg_program_test(argv[i + 1])) {
                printf("PASS %s\n", argv[i]);
            } else {
                failed++;
                printf("FAIL %s: %s\n", argv[i], vg_failure);
            }
        }
        if (failed) printf("%d test(s) failed.\n", failed);
        else printf("All tests passed.\n");
        return failed ? 1 : 0;
    }
    vg_program_start();
    return 0;
}
